beforeExample:
package org.eclipse.debug.tests;
import org.eclipse.core.runtime.IStatus;
public class TestUtil {
    public static void log(int severity, String owner, String message) {
        System.err.println("[" + owner + "] " + message);
    }
    public static void log(int severity, String owner, String message, Throwable t) {
        System.err.println("[" + owner + "] " + message + " : " + t.getMessage());
        t.printStackTrace();
    }
    public void someMethod() {
        String owner = "MyTest";
        String message = "Some job is still running or waiting to run: ";
        log(IStatus.ERROR, owner, message);
    }
}

