package org.eclipse.debug.tests;
import org.eclipse.core.runtime.IStatus;
public class TestUtil {
    public static void log(int severity, String owner, String message) {
        System.err.println("[" + owner + "] " + message);
    }
    public static void log(int severity, String owner, String message, Throwable t) {
        System.err.println("[" + owner + "] " + message + " : " + t.getMessage());
        t.printStackTrace();
    }
    public void someOtherMethod() {
        String owner = "MyTest";
        String message = "Informational message";
        log(IStatus.INFO, owner, message); // Different severity, should not match
    }
    public void yetAnotherMethod() {
        String owner = "MyTest";
        String message = "Error message with existing exception";
        log(IStatus.ERROR, owner, message, new IllegalArgumentException("Existing cause")); // Already has Throwable, should not match
    }
}
